    ["So wird gemessen"] = "How it is measured",
    ["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "After every fight Oasis reads Blizzard's built-in damage meter - the combat log is locked for addons in WoW Forever. Others need Oasis 0.5.577 or newer. Values Blizzard keeps secret (e.g. in instances) don't count.",
    ["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "No values yet - after the next fight you'll see who is ahead.",
    ["Blizzards Schadensanzeige ist in diesem Client nicht verfuegbar - Ranglisten koennen nicht gemessen werden."] = "Blizzard's damage meter is not available in this client - rankings can't be measured.",
