EN["Oasis: Fenster auf"] = "Oasis: Window open"
EN["Oasis: Fenster zu"] = "Oasis: Window close"
EN["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Who has which buffs in the group or raid - and who can provide what is missing"
EN["Termine, Anmeldung und Raidleitung"] = "Events, sign-ups and raid leading"
EN["Termine anlegen, Beute verteilen, Aufstellung und Punkte"] = "Create events, distribute loot, line-up and points"
EN["Faire Beute: wer oft dabei ist und wenig bekommen hat, ist zuerst dran"] = "Fair loot: whoever attends often and has received little goes first"
EN["Gilden-Sammelkarte: Fundorte, die jemand aus der Gilde gefunden hat"] = "Guild gathering map: spots found by someone in the guild"
EN["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "Your guild's hub. In 30 seconds you will know your way around - here is what matters."
EN["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."
EN["Zeigt sofort, wer aus der Gilde dieselben Quests hat und gerade online ist - ein Klick laedt ihn ein."] = "Shows at a glance who in the guild has the same quests and is online right now - one click invites them."
EN["Hier passiert alles"] = "This is where it happens"
EN["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "The content of the selected area. The overview shows who is online, what is coming up and what is new."
EN["Einstellungen und Sprache"] = "Settings and language"
EN["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Gear = settings (look, sounds, notifications). Next to it the language and - for guild leadership - the crown."
EN["Immer griffbereit"] = "Always at hand"
EN["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "The minimap button or /oa opens Oasis. The dash at the top right turns the window into a slim bar."
EN["Viel Spass mit Oasis!"] = "Have fun with Oasis!"
EN["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "That's it. You can find the tour again any time under Settings > Status or with /oa rundgang."
EN["Befoerderung vorschlagen nach"] = "Suggest promotion after"
EN["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."
EN["Rueckkehrer melden"] = "Report returning members"
EN["Kommt ein ehemaliges Mitglied zurueck, bekommt die Gildenleitung einen Hinweis mit dem frueheren Rang und Austrittsdatum."] = "When a former member comes back, guild leadership gets a notice with their former rank and leave date."
EN["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Rolling: order need > off-spec > transmog, then the roll. Points: priority from loot points decides. Loot council: officers vote, the master looter awards."
EN["Erstes Gebot je Item in Gold."] = "First bid per item in gold."
EN["Um so viel Gold muss jedes neue Gebot hoeher sein."] = "Every new bid must be higher by this much gold."
EN["GDKP: Anteil Gildenbank"] = "GDKP: guild bank share"
EN["So viel Prozent vom Topf gehen vor dem Aufteilen an die Gildenbank."] = "This percentage of the pot goes to the guild bank before the split."
EN["So lange hat jeder Zeit zu waehlen. Wer nichts waehlt, passt."] = "This is how long everyone has to choose. Whoever chooses nothing passes."
EN["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Whoever already received an item on need that evening drops behind everyone without an item on need (same roll rank)."
EN["Soft-Reserve zuerst"] = "Soft reserve first"
EN["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Whoever reserved an item for the event comes before everyone else on need."
EN["Beuterat ab Rang"] = "Loot council from rank"
EN["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "These guild ranks (0 = guild master) may vote in the loot council."
EN["Items ab dieser Qualitaet kommen in die Verteilung."] = "Items of this quality and above go into distribution."
EN["Was liegt wo? Suche ueber alle deine Charaktere, ihre Bank und die Gildenbank"] = "What is where? Search across all your characters, their bank and the guild bank"
EN["Zielt jemand einen Boss an, zu dem es eine Taktik gibt, erscheint ein kurzer Hinweis (ausserhalb des Kampfes)."] = "When someone targets a boss that has a tactic, a short notice appears (out of combat)."
EN["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."
EN["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."
EN["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."
EN["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."
EN["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."
EN["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."
EN["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."
EN["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."
EN["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."
EN["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."
EN["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."
EN["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."
EN["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."
EN["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."
EN["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."
EN["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."
EN["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."
EN["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."
EN["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."
EN["Bereit fuer den Pull? Bereitschaft, Verzauberungen und Buffs je Spieler"] = "Ready for the pull? Readiness, enchants and buffs per player"
